{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Keep Adam and the baseline peak learning rate, with linear warmup over the first 5% of configured epochs followed by cosine decay to 10% of peak. This may stabilize early updates and improve late ranking refinement. Preserve architecture, loss, batch size, dropout, weight decay, seeds, evaluation, and one checkpoint per category.",
      "edits": [
        {
          "find": "NUM_EPOCHS   = int(os.environ.get(\"SASREC_EPOCHS\",    \"300\"))",
          "replace": "NUM_EPOCHS   = min(200, int(os.environ.get(\"SASREC_EPOCHS\", \"200\")))"
        },
        {
          "find": "    for epoch in range(1, NUM_EPOCHS + 1):\n        model.train()\n        total_loss = 0.0",
          "replace": "    warmup_epochs = max(1, math.ceil(0.05 * NUM_EPOCHS))\n\n    for epoch in range(1, NUM_EPOCHS + 1):\n        if epoch <= warmup_epochs:\n            lr_scale = epoch / warmup_epochs\n        else:\n            progress = (epoch - warmup_epochs) / max(1, NUM_EPOCHS - warmup_epochs)\n            lr_scale = 0.1 + 0.9 * 0.5 * (1.0 + math.cos(math.pi * progress))\n        for param_group in optimizer.param_groups:\n            param_group[\"lr\"] = LR * lr_scale\n\n        model.train()\n        total_loss = 0.0"
        }
      ]
    }
  ],
  "change_summary": "Add epoch-based 5% linear warmup and cosine learning-rate decay, enforcing the 200-epoch cap. Predictor and checkpoint formats remain compatible."
}
